static JSValue js_TileData_set_collision_polygon_points(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "TileData.set_collision_polygon_points: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "TileData.set_collision_polygon_points: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "TileData.set_collision_polygon_points: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "TileData.set_collision_polygon_points: invalid or freed object");
    }

    TileData* typed_obj = Object::cast_to<TileData>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "TileData.set_collision_polygon_points: object is not a TileData");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 4) {
        return JS_ThrowTypeError(ctx, "TileData.set_collision_polygon_points: expected at least 3 arguments, got %d", argc - 1);
    }

    // Convert arguments
    int64_t arg_layer_id; JS_ToInt64(ctx, &arg_layer_id, argv[1]);
    int64_t arg_polygon_index; JS_ToInt64(ctx, &arg_polygon_index, argv[2]);
    PackedVector2Array arg_polygon;
    if (JS_IsArray(argv[3])) {
        JSValue len_val = JS_GetPropertyStr(ctx, argv[3], "length");
        int64_t len = 0; JS_ToInt64(ctx, &len, len_val); JS_FreeValue(ctx, len_val);
        arg_polygon.resize(len);
        for (int64_t i = 0; i < len; i++) {
            JSValue elem = JS_GetPropertyUint32(ctx, argv[3], i);
            double x = 0, y = 0;
            JSValue jx = JS_GetPropertyStr(ctx, elem, "x");
            JSValue jy = JS_GetPropertyStr(ctx, elem, "y");
            JS_ToFloat64(ctx, &x, jx); JS_ToFloat64(ctx, &y, jy);
            JS_FreeValue(ctx, jx); JS_FreeValue(ctx, jy);
            JS_FreeValue(ctx, elem);
            arg_polygon.set(i, Vector2(x, y));
        }
    }

    typed_obj->set_collision_polygon_points(arg_layer_id, arg_polygon_index, arg_polygon);
    return JS_UNDEFINED;
}

